python3 << 'PYEOF'
import os
import re
from collections import defaultdict

REPO = "/bench/repo"

# Persistent entity types - main table-mapped structs from store/*.go (not Find/Update/Delete/Mutation)
ENTITY_TYPES = [
    "Attachment", "Memo", "MemoRelation", "InstanceSetting", "User", "UserSetting",
    "IdentityProvider", "Inbox", "Reaction", "MemoShare", "UserIdentity",
    "AuthenticationConfigState",
]

def get_package(path):
    """Return Go package path relative to repo root (directory containing the .go file)."""
  # e.g. /bench/repo/server/router/api/v1/foo.go -> server/router/api/v1
    rel = os.path.relpath(path, REPO)
    return os.path.dirname(rel)

def is_store_layer(pkg):
    return pkg == "store" or pkg.startswith("store/")

# Patterns for referencing store entity types
def patterns(entity):
    return [
        re.compile(r'\bstore\.' + entity + r'\b'),
        re.compile(r'\*store\.' + entity + r'\b'),
        re.compile(r'\[\]store\.' + entity + r'\b'),
        re.compile(r'\[\]\*store\.' + entity + r'\b'),
        re.compile(r'map\[[^\]]*\]\*?store\.' + entity + r'\b'),
    ]

entity_packages = defaultdict(set)
all_go_files = []

for root, dirs, files in os.walk(REPO):
    # skip .git
    dirs[:] = [d for d in dirs if d != '.git' and d != 'node_modules']
    for f in files:
        if f.endswith('.go'):
            all_go_files.append(os.path.join(root, f))

for filepath in all_go_files:
    pkg = get_package(filepath)
    if is_store_layer(pkg):
        continue
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as fh:
            content = fh.read()
    except Exception:
        continue
    for entity in ENTITY_TYPES:
        for pat in patterns(entity):
            if pat.search(content):
                entity_packages[entity].add(pkg)
                break

# Sort by count
ranked = sorted(ENTITY_TYPES, key=lambda e: len(entity_packages[e]), reverse=True)

print("=== Entity type references by distinct external packages ===")
for entity in ranked:
    pkgs = sorted(entity_packages[entity])
    print(f"{entity}: {len(pkgs)} packages")
    for p in pkgs:
        print(f"  - {p}")
    print()
PYEOF

