perl << 'PERL'
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";
my @ENTITIES = qw(
    Attachment Memo MemoRelation InstanceSetting User UserSetting
    IdentityProvider Inbox Reaction MemoShare UserIdentity
    AuthenticationConfigState
);

my %entity_packages;
for my $e (@ENTITIES) { $entity_packages{$e} = {} }

sub is_store_layer {
    my ($pkg) = @_;
    return $pkg eq "store" || $pkg =~ /^store\//;
}

sub get_package {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\/?//;
    my $dir = dirname($rel);
    return $dir eq "." ? "" : $dir;
}

find({
    wanted => sub {
        return unless $_ =~ /\.go$/;
        my $path = $File::Find::name;
        my $pkg = get_package($path);
        return if is_store_layer($pkg);

        open my $fh, '<', $path or return;
        local $/;
        my $content = <$fh>;
        close $fh;

        for my $entity (@ENTITIES) {
            if ($content =~ /\bstore\.$entity\b/ || 
                $content =~ /\*store\.$entity\b/ ||
                $content =~ /\[\]store\.$entity\b/ ||
                $content =~ /\[\]\*store\.$entity\b/ ||
                $content =~ /map\[[^\]]*\]\*?store\.$entity\b/) {
                $entity_packages{$entity}{$pkg} = 1;
            }
        }
    },
    no_chdir => 1,
}, $REPO);

# Sort by count
my @ranked = sort { 
    (scalar keys %{$entity_packages{$b}}) <=> (scalar keys %{$entity_packages{$a}}) 
} @ENTITIES;

print "=== Entity type references by distinct external packages ===\n";
for my $entity (@ranked) {
    my @pkgs = sort keys %{$entity_packages{$entity}};
    print "$entity: " . scalar(@pkgs) . " packages\n";
    for my $p (@pkgs) {
        print "  - $p\n";
    }
    print "\n";
}
PERL

